-- Real PostgreSQL assertions. Fixtures and all changes roll back.
BEGIN;
DO $$
DECLARE
 owner uuid:=gen_random_uuid(); other_owner uuid:=gen_random_uuid(); auth_session uuid:=gen_random_uuid(); other_session uuid:=gen_random_uuid();
 auth_data jsonb; other_auth jsonb; s jsonb; c jsonb; c2 jsonb; r jsonb; device uuid; request_id uuid:=gen_random_uuid();
 event_id uuid:=gen_random_uuid(); other_event uuid:=gen_random_uuid(); payload jsonb; bad_payload jsonb;
 stamp text:=to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'); day text:=to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD');
BEGIN
 INSERT INTO auth.users(id) VALUES(owner),(other_owner);
 INSERT INTO auth.sessions(id,user_id) VALUES(auth_session,owner),(other_session,other_owner);
 auth_data:=jsonb_build_object('auth_session_id',auth_session); other_auth:=jsonb_build_object('auth_session_id',other_session);
 IF public.badge_gateway('create_pairing',owner,jsonb_build_object('code_hash',repeat('a',64)))->>'error'<>'unauthorized' THEN RAISE EXCEPTION 'missing owner session accepted'; END IF;
 s:=public.badge_gateway('create_pairing',owner,auth_data||jsonb_build_object('code_hash',repeat('a',64)));
 IF s->>'state'<>'pending' THEN RAISE EXCEPTION 'session not created: %',s; END IF;
 c:=public.badge_gateway('claim',NULL,jsonb_build_object('code_hash',repeat('a',64),'pending_hash',repeat('b',64),'credential_hash',repeat('c',64),'verification_id','ABCD-1234'));
 IF c->>'state'<>'pending' THEN RAISE EXCEPTION 'claim not pending: %',c; END IF;
 r:=public.badge_gateway('claim',NULL,jsonb_build_object('code_hash',repeat('a',64),'pending_hash',repeat('b',64),'credential_hash',repeat('c',64),'verification_id','FFFF-0000'));
 IF r<>c THEN RAISE EXCEPTION 'claim retry changed binding'; END IF;
 IF public.badge_gateway('claim',NULL,jsonb_build_object('code_hash',repeat('a',64),'pending_hash',repeat('b',64),'credential_hash',repeat('d',64)))->>'error'<>'pairing_unavailable' THEN RAISE EXCEPTION 'pending secret rebound'; END IF;
 c2:=public.badge_gateway('claim',NULL,jsonb_build_object('code_hash',repeat('a',64),'pending_hash',repeat('d',64),'credential_hash',repeat('e',64),'verification_id','1234-ABCD'));
 IF public.badge_gateway('token',NULL,jsonb_build_object('credential_hash',repeat('c',64)))->>'error'<>'unauthorized' THEN RAISE EXCEPTION 'unapproved token issued'; END IF;
 IF public.badge_gateway('approve_claim',other_owner,other_auth||jsonb_build_object('session_id',s->>'session_id','claim_id',c->>'claim_id'))->>'error'<>'not_found' THEN RAISE EXCEPTION 'other owner approval'; END IF;
 r:=public.badge_gateway('approve_claim',owner,auth_data||jsonb_build_object('session_id',s->>'session_id','claim_id',c->>'claim_id','name','Desk badge'));
 IF r->>'state'<>'approved' THEN RAISE EXCEPTION 'approval failed: %',r; END IF;
 device:=(r->>'device_id')::uuid;
 IF public.badge_gateway('approve_claim',owner,auth_data||jsonb_build_object('session_id',s->>'session_id','claim_id',c->>'claim_id'))<>r THEN RAISE EXCEPTION 'duplicate approval changed registration'; END IF;
 IF public.badge_gateway('approve_claim',owner,auth_data||jsonb_build_object('session_id',s->>'session_id','claim_id',c2->>'claim_id'))->>'error'<>'pairing_unavailable' THEN RAISE EXCEPTION 'sibling claim approved'; END IF;
 IF public.badge_gateway('claim',NULL,jsonb_build_object('code_hash',repeat('a',64),'pending_hash',repeat('b',64),'credential_hash',repeat('c',64),'verification_id','ABCD-1234'))->>'claim_id'<>c->>'claim_id' THEN RAISE EXCEPTION 'approved claim retry lost registration'; END IF;
 UPDATE private.badge_pairing_sessions SET expires_at=now()-interval '1 hour' WHERE id=(s->>'session_id')::uuid;
 r:=public.badge_gateway('poll',NULL,jsonb_build_object('pending_hash',repeat('b',64)));
 IF r->>'state'<>'approved' OR r->>'device_id'<>device::text OR r ? 'credential' OR r ? 'credential_hash' THEN RAISE EXCEPTION 'lost approval recovery failed or leaked secret'; END IF;
 IF public.badge_gateway('poll',NULL,jsonb_build_object('pending_hash',repeat('d',64)))->>'state'<>'expired' THEN RAISE EXCEPTION 'sibling poll misrepresented'; END IF;
 r:=public.badge_gateway('ack',NULL,jsonb_build_object('credential_hash',repeat('c',64)));
 IF r->>'state'<>'active' OR r->>'owner_id'<>owner::text THEN RAISE EXCEPTION 'credential acknowledgement failed'; END IF;
 IF public.badge_gateway('ack',NULL,jsonb_build_object('credential_hash',repeat('c',64)))<>r THEN RAISE EXCEPTION 'ack not idempotent'; END IF;
 IF public.badge_gateway('status_pairing',owner,auth_data||jsonb_build_object('session_id',s->>'session_id'))->>'state'<>'delivered' THEN RAISE EXCEPTION 'delivery not recorded'; END IF;
 IF public.badge_gateway('token',NULL,jsonb_build_object('credential_hash',repeat('c',64)))->>'owner_id'<>owner::text THEN RAISE EXCEPTION 'token identity wrong'; END IF;
 payload:=jsonb_build_object('credential_hash',repeat('c',64),'request_id',request_id,'payload_hash',repeat('f',64),'events',jsonb_build_array(jsonb_build_object('id',event_id,'type','hydration','occurred_at',stamp,'day_key',day)));
 r:=public.badge_gateway('upload',NULL,payload);
 IF r->>'state'<>'accepted' OR r->>'accepted'<>'1' THEN RAISE EXCEPTION 'upload failed: %',r; END IF;
 IF public.badge_gateway('upload',NULL,payload)<>r THEN RAISE EXCEPTION 'lost reply not idempotent'; END IF;
 IF (SELECT count(*) FROM public.wellness_events WHERE owner_id=owner)<>1 OR (SELECT count(*) FROM private.badge_upload_receipts WHERE device_id=device)<>1 THEN RAISE EXCEPTION 'retry duplicated writes'; END IF;
 IF (SELECT badge_projection.payload::jsonb->>'hydration_count' FROM public.badge_projection WHERE owner_id=owner AND kind='summary')<>'1' THEN RAISE EXCEPTION 'projection did not include upload'; END IF;
 IF public.badge_gateway('upload',NULL,payload||jsonb_build_object('payload_hash',repeat('0',64)))->>'error'<>'request_conflict' THEN RAISE EXCEPTION 'changed receipt accepted'; END IF;
 bad_payload:=payload||jsonb_build_object('request_id',gen_random_uuid(),'events',jsonb_build_array(jsonb_build_object('id',other_event,'type','movement','occurred_at',stamp,'day_key',day),jsonb_build_object('id',gen_random_uuid(),'type','hydration','occurred_at',stamp,'day_key','1999-01-01')));
 IF public.badge_gateway('upload',NULL,bad_payload)->>'error'<>'invalid_events' OR EXISTS(SELECT 1 FROM public.wellness_events WHERE id=other_event::text) THEN RAISE EXCEPTION 'invalid batch partially accepted'; END IF;
 IF public.badge_gateway('upload',NULL,payload||jsonb_build_object('request_id',gen_random_uuid(),'events',jsonb_build_array(jsonb_build_object('id',event_id,'type','movement','occurred_at',stamp,'day_key',day))))->>'error'<>'event_conflict' THEN RAISE EXCEPTION 'immutable event changed'; END IF;
 -- Canonical web writes update projections too, including deletes.
 INSERT INTO public.wellness_events VALUES(other_event::text,owner,day,'movement',stamp);
 IF (SELECT badge_projection.payload::jsonb->>'movement_count' FROM public.badge_projection WHERE owner_id=owner AND kind='summary')<>'1' THEN RAISE EXCEPTION 'web insert not projected'; END IF;
 DELETE FROM public.wellness_events WHERE id=other_event::text;
 IF (SELECT badge_projection.payload::jsonb->>'movement_count' FROM public.badge_projection WHERE owner_id=owner AND kind='summary')<>'0' THEN RAISE EXCEPTION 'web delete not projected'; END IF;
 PERFORM public.pet_ai_ensure(owner,'cat','Cat');
 UPDATE public.pet_sessions SET bio_name=repeat('🦊',1000),latest_speech=repeat('🦊',1000),animal_id=repeat('🦊',1000) WHERE owner_id=owner;
 IF EXISTS(SELECT 1 FROM public.badge_projection WHERE owner_id=owner AND octet_length(badge_projection.payload)>1536) OR (SELECT count(*) FROM public.badge_projection WHERE owner_id=owner)>3 THEN RAISE EXCEPTION 'projection bound exceeded'; END IF;
 IF public.badge_gateway('revoke_device',other_owner,other_auth||jsonb_build_object('device_id',device))->>'error'<>'not_found' THEN RAISE EXCEPTION 'other owner revoked device'; END IF;
 r:=public.badge_gateway('revoke_device',owner,auth_data||jsonb_build_object('device_id',device));
 IF r->>'state'<>'revoked' THEN RAISE EXCEPTION 'revoke failed'; END IF;
 IF public.badge_gateway('token',NULL,jsonb_build_object('credential_hash',repeat('c',64)))->>'error'<>'unauthorized' OR public.badge_gateway('upload',NULL,payload)->>'error'<>'unauthorized' THEN RAISE EXCEPTION 'revocation allowed token or receipt retry'; END IF;
 s:=public.badge_gateway('create_pairing',owner,auth_data||jsonb_build_object('code_hash',repeat('0',64)));
 PERFORM public.badge_gateway('cancel_pairing',owner,auth_data||jsonb_build_object('session_id',s->>'session_id'));
 IF public.badge_gateway('claim',NULL,jsonb_build_object('code_hash',repeat('0',64),'pending_hash',repeat('1',64),'credential_hash',repeat('2',64),'verification_id','1234-5678'))->>'error'<>'pairing_unavailable' THEN RAISE EXCEPTION 'cancelled claim accepted'; END IF;
 s:=public.badge_gateway('create_pairing',owner,auth_data||jsonb_build_object('code_hash',repeat('0',64)));
 UPDATE private.badge_pairing_sessions SET expires_at=now()-interval '1 second' WHERE id=(s->>'session_id')::uuid;
 IF public.badge_gateway('status_pairing',owner,auth_data||jsonb_build_object('session_id',s->>'session_id'))->>'state'<>'expired' THEN RAISE EXCEPTION 'expiry not observed'; END IF;
 DELETE FROM auth.sessions WHERE id=auth_session;
 IF public.badge_gateway('list_devices',owner,auth_data)->>'error'<>'unauthorized' THEN RAISE EXCEPTION 'signed out owner accepted'; END IF;
 IF NOT public.badge_rate_limit('test',owner::text,2) OR NOT public.badge_rate_limit('test',owner::text,2) OR public.badge_rate_limit('test',owner::text,2) OR public.badge_rate_limit('test',owner::text,2) THEN RAISE EXCEPTION 'rate limit ineffective'; END IF;
 IF has_table_privilege('authenticated','private.badge_credentials','SELECT') OR has_table_privilege('anon','private.badge_pending_claims','SELECT') OR has_function_privilege('authenticated','public.badge_gateway(text,uuid,jsonb)','EXECUTE') OR has_table_privilege('authenticated','public.badge_projection','INSERT') THEN RAISE EXCEPTION 'client bypass privilege'; END IF;
 IF EXISTS(SELECT 1 FROM pg_publication_tables WHERE pubname='powersync' AND schemaname='private') THEN RAISE EXCEPTION 'private material in publication'; END IF;
END $$;
ROLLBACK;
